class Memoize:
    def __init__(self, func):
        self.func = func
        self.cache = {}

    def __call__(self, *args, **kwargs):
        key = (args, frozenset(kwargs.items()))
        if key not in self.cache:
            self.cache[key] = self.func(*args, **kwargs)
        return self.cache[key]

class Cache:
    def __init__(self):
        self.cache = {}

    def invalidate(self, key):
        if key in self.cache:
            del self.cache[key]

    def invalidate_all(self):
        self.cache.clear()

    def __getitem__(self, key):
        return self.cache.get(key, None)

def reraise(exc):
    try:
        yield
    except Exception as e:
        if hasattr(e, 'original_exc'):
            e.original_exc = exc
        raise e from exc.original_exc if hasattr(e, 'original_exc') else e

def api_call(f, callback):
    try:
        yield
    except Exception as e:
        callback(e)

def decorator(func):
    def wrapper(*args, **kwargs):
        if has_1pos_and_kwonly(func):
            return rcurry(func)(*args, **kwargs)
        else:
            return func(*args, **kwargs)

def get_spec(func):
    if hasattr(func, 'spec'):
        return func.spec
    else:
        return inspect.signature(func)

def throttle(rate, timedelta):
    if isinstance(timedelta, timedelta):
        return rate * timedelta.total_seconds()
    else:
        raise ValueError("timedelta argument must be a timedelta object")
